#include <noarr/structures/interop/serialize_data.hpp>

#include "defines.hpp"
#include "bicg.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A: i x j (row-major: j is the inner/fast dimension)
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);

	// 1D vectors
	DEFINE_PROTO_STRUCT(s_layout, j_vec); // length M, index 'j'
	DEFINE_PROTO_STRUCT(q_layout, i_vec); // length N, index 'i'
	DEFINE_PROTO_STRUCT(p_layout, j_vec); // length M, index 'j'
	DEFINE_PROTO_STRUCT(r_layout, i_vec); // length N, index 'i'
} tuning;

// Array initialization
// A: i x j
// r: i
// p: j
//
// The loops are already cache-friendly (row-major in A).
// We only hoist invariant length queries out of the traverser bodies.
void init_array(auto A, auto r, auto p) {
	using namespace noarr;

	// Query lengths once; static lengths collapse to constants,
	// dynamic lengths are read only once here.
	const std::size_t m = p | get_length<'j'>();
	const std::size_t n = r | get_length<'i'>(); // == A | get_length<'i'>()

	// p[j] = (j % m) / m;
	traverser(p).for_each([&](auto state) {
		const std::size_t j = get_index<'j'>(state);
		p[state] = static_cast<num_t>(j % m) / static_cast<num_t>(m);
	});

	// r[i] = (i % n) / n;
	traverser(r).for_each([&](auto state) {
		const std::size_t i = get_index<'i'>(state);
		r[state] = static_cast<num_t>(i % n) / static_cast<num_t>(n);
	});

	// A[i][j] = (i * (j + 1) % n) / n;
	// Traversal is i-major, j-minor (row-major), matching the layout.
	traverser(A).for_each([&](auto state) {
		const auto [i, j] = get_indices<'i', 'j'>(state);
		A[state] = static_cast<num_t>((i * (j + 1)) % n) / static_cast<num_t>(n);
	});
}

// Main computational kernel
// A: i x j
// s: j
// q: i
// p: j
// r: i
//
// Original algorithm:
//
//   s[j] = 0
//   for i:
//     q[i] = 0
//     for j:
//       s[j] += r[i] * A[i][j];
//       q[i] += A[i][j] * p[j];
//
// Optimizations applied:
//
// - Keep traversal order i-major, j-minor to match row-major storage of A.
// - Hoist r[i] out of the inner j-loop to a scalar r_i.
// - Accumulate q[i] in a scalar q_i in registers and write it back once
//   after finishing the inner loop (removes repeated loads/stores of q[i]).
// - Keep s[j] streaming and contiguous in the inner loop.
// - Use reference captures in lambdas to avoid unnecessary bag copies.
[[gnu::flatten, gnu::noinline]]
void kernel_bicg(auto A, auto s, auto q, auto p, auto r) {
	using namespace noarr;

	#pragma scop
	// s[j] = 0 for all j
	traverser(s).for_each([&](auto state) {
		s[state] = SCALAR_VAL(0.0);
	});

	// For each i:
	//   q[i] = sum_j A[i][j] * p[j]
	//   s[j] += r[i] * A[i][j]  (accumulated over all i)
	traverser(A, s, q, p, r).template for_dims<'i'>([&](auto inner) {
		// state with current i fixed
		auto istate = inner.state(); // contains only 'i'

		// r[i] is invariant w.r.t. j, hoist to a scalar
		const num_t r_i = r[istate];

		// Accumulator for q[i] kept in registers; initialized to 0
		num_t q_i = SCALAR_VAL(0.0);

		// loop over j (inner, contiguous in A and in s / p)
		inner.for_each([&](auto state) {
			// state has both 'i' and 'j'
			const num_t a_ij = A[state];
			const num_t p_j  = p[state]; // r/ q / s / p ignore extra dims they do not have

			// s[j] += r[i] * A[i][j];
			s[state] += r_i * a_ij;

			// q_i accumulates q[i] over j
			q_i += a_ij * p_j;
		});

		// Store final q[i] once after finishing all j for this i
		q[istate] = q_i;
	});
	#pragma endscop
}

